for key,v in e['views'].items():
 p=R/(key+'.png');assert sha(p)==v['image_sha256'];assert list(Image.open(p).size)==v['resolution']==[640,360];assert v['executed_script_sha256']==e['executed_script_sha256'];assert v['open_export_sha256']==e['state_derivative']['open_sha256']
 for ident,h in v['source_scope'].items():assert h==next(x['hashes']['path']for x in e['items']if x['catalogue_id']==ident)
